e:10px;font-weight:850;cursor:pointer}.ed-history-cleanup-actions .is-danger{border-color:#dc2626;background:#dc2626;color:#fff}.ed-history-cleanup-actions button:disabled{cursor:not-allowed;opacity:.55}html.history-drawer-open,body.history-drawer-open{overflow:hidden!important}
